  ('ai:ai-batch-06:0d3c9003530b','A2'::public.cefr_level,'reading','What time did the grandfather get up?',array['at midnight','at five','at six','at seven']::text[],'B','''My grandfather got up at five to milk the cows.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When I was a child, we never went abroad on holiday. Every August we drove to my grandparents'' farm in Wales. My grandfather got up at five to milk the cows, and I sometimes helped him. In the evenings there was no television, so we played cards or listened to my grandmother''s stories. At the time I wanted to go to Spain like my friends, but now those are my happiest memories.',null,null,null,'exam'),
  ('ai:ai-batch-06:c27ed98a6371','A2'::public.cefr_level,'reading','Where is the flat?',array['on the ground floor','on the first floor','above a shop','far from the station']::text[],'B','''Two bedrooms, first floor.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','FLAT TO RENT — Two bedrooms, first floor, five minutes'' walk from the station. Fully furnished, with a new kitchen. Rent: £850 a month, plus bills. No pets. Available from 1st March. Students welcome. To arrange a visit, email Mr Patel (no phone calls after 8 pm).',null,null,null,'exam'),
  ('ai:ai-batch-06:6fea98918821','A2'::public.cefr_level,'reading','When is the flat available?',array['now','after 8 pm','from 1st May','from 1st March']::text[],'D','''Available from 1st March.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','FLAT TO RENT — Two bedrooms, first floor, five minutes'' walk from the station. Fully furnished, with a new kitchen. Rent: £850 a month, plus bills. No pets. Available from 1st March. Students welcome. To arrange a visit, email Mr Patel (no phone calls after 8 pm).',null,null,null,'exam'),
  ('ai:ai-batch-06:6a45d12423bd','A2'::public.cefr_level,'reading','What should runners bring?',array['a bike','a towel and a coat','a bottle of water','£20 each time']::text[],'C','''Wear comfortable shoes and bring a bottle of water.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Riverside Running Club meets every Tuesday and Thursday at 6.30 pm outside the sports centre. Beginners are welcome: on Tuesdays there is a slower group that runs 3 km. On Thursdays we run 8 km along the river. The first two sessions are free; after that membership costs £20 a year. Wear comfortable shoes and bring a bottle of water. We don''t run if there is ice on the paths.',null,null,null,'exam'),
  ('ai:ai-batch-06:129594234ab2','A2'::public.cefr_level,'reading','What does Hannah do at work most of the day?',array['designs gardens','drives a van','answers emails','helps customers choose plants']::text[],'D','''Helping customers to choose plants.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Hannah started a new job last month at a garden centre near Bristol. Before that, she worked in an office for six years, but she was bored because she sat at a computer all day. Now she spends most of the day outside, helping customers to choose plants. The pay is lower than in her old job, so she cycles to work instead of driving to save money. She says she feels healthier and much happier. Next spring she is going to start a course in garden design.',null,null,null,'exam'),
  ('ai:ai-batch-06:7d080e5bbb0d','A2'::public.cefr_level,'grammar','It ___ a lot in Wales, so take a raincoat.',array['rained','rains','rain','is raining now']::text[],'B','General facts use the present simple.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:084a7139c4f2','A2'::public.cefr_level,'grammar','He drove ___ because the road was icy.',array['slowest','slow','more slow','slowly']::text[],'D','Adverbs (slowly) describe how we do something.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:98c3d08a6e58','A2'::public.cefr_level,'grammar','___ I open the window? It''s hot in here.',array['Do','Will','Am','Shall']::text[],'D','We offer to do something with ''Shall I...?''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:b9c2655a1abc','A2'::public.cefr_level,'vocabulary','I''d like to ___ this jumper back. It''s too small.',array['bring up','give up','take','put']::text[],'C','You take something back to a shop.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8efda2d61c86','A2'::public.cefr_level,'vocabulary','The hotel ___ breakfast from 7 to 10.',array['eats','makes up','cooks for','serves']::text[],'D','Hotels and restaurants serve meals.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:9e9e725140c3','A2'::public.cefr_level,'vocabulary','She ___ a cold, so she stayed in bed.',array['made','took','caught','got off']::text[],'C','You catch a cold.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d16f2423aa84','B1'::public.cefr_level,'grammar','If I ___ more time, I would learn to play the piano.',array['had','would have','will have','have']::text[],'A','Second conditional: if + past simple, would + verb.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:81b05ef75ab5','B1'::public.cefr_level,'grammar','She said that she ___ tired.',array['has been','was','will be','is']::text[],'B','In reported speech the present usually moves back to the past.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:3258c4b01bbb','B1'::public.cefr_level,'grammar','The letter ___ yesterday, so it should arrive soon.',array['posted','is posting','has posted','was posted']::text[],'D','Past passive: was + past participle.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
