  ('ai:ai-batch-06:ed74b039b88a','B1'::public.cefr_level,'grammar','By the time she arrived, the film ___.',array['has already started','was already starting','had already started','already started']::text[],'C','An action completed before another past action: past perfect.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:79d2532047d1','B1'::public.cefr_level,'grammar','He''s used to ___ early, so the new job isn''t a problem.',array['getting up','have got up','get up','got up']::text[],'A','''Be used to'' is followed by -ing.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
