  ('ai:ai-batch-06:07157a8f9716','B1'::public.cefr_level,'grammar','The car ___ is parked outside belongs to my neighbour.',array['who','which','whose','what']::text[],'B','''Which'' introduces a relative clause about a thing.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:055bcf9df7c6','B1'::public.cefr_level,'grammar','That''s the woman ___ son plays for Arsenal.',array['who','which','whose','who''s']::text[],'C','''Whose'' shows possession in relative clauses.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:0e742b59f73c','B1'::public.cefr_level,'grammar','I''ve been waiting here ___ two o''clock.',array['ago','for','since','from']::text[],'C','''Since'' + point in time.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:9e5843bd4222','B1'::public.cefr_level,'grammar','She ___ in the same company for fifteen years.',array['works','has been working','is working','worked since']::text[],'B','Duration up to now: present perfect continuous.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e6ab495cd514','B1'::public.cefr_level,'grammar','Unless you ___ now, you''ll miss the train.',array['will leave','don''t leave','left','leave']::text[],'D','''Unless'' means ''if not'' and is followed by a positive verb.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
