  ('ai:ai-batch-06:3c257b949cd4','B1'::public.cefr_level,'grammar','It ___ be Anna at the door — she''s on holiday in Spain.',array['doesn''t','can''t','mustn''t','shouldn''t']::text[],'B','''Can''t'' expresses that something is impossible.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
