  ('ai:ai-batch-06:ff2860be2eb2','B1'::public.cefr_level,'grammar','I''m going to have my hair ___ tomorrow.',array['cutting','cut','to cut','cuts']::text[],'B','''Have something done'' = have + object + past participle.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:0a4819921b12','B1'::public.cefr_level,'grammar','If she had studied, she ___ the exam.',array['will pass','would pass','passed','would have passed']::text[],'D','Third conditional: would have + past participle.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
