  ('ai:ai-batch-06:630ad9611b1a','B1'::public.cefr_level,'grammar','I remember ___ this film before. I know the ending.',array['see','to see','to seeing','seeing']::text[],'D','''Remember + -ing'' refers to a past memory.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:94f2e60f40a9','B1'::public.cefr_level,'grammar','Remember ___ the door when you leave.',array['to lock','lock','locking','locked']::text[],'A','''Remember + to'' refers to a future duty.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
