  ('ai:ai-batch-06:0c74640531a1','B1'::public.cefr_level,'vocabulary','I didn''t ___ to offend you. I''m sorry.',array['want say','mean','think','intend on']::text[],'B','''I didn''t mean to'' = it wasn''t my intention.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8880c53a9d6b','B1'::public.cefr_level,'vocabulary','The ___ of living in London is very high.',array['charge','value','price','cost']::text[],'D','We talk about ''the cost of living''.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
