  ('ai:ai-batch-06:41be40499aab','B1'::public.cefr_level,'vocabulary','The road was closed, so we had to take a ___.',array['journey back','shortcut','detour','tour']::text[],'C','A detour is a longer way round something.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8eefef2b02fe','B1'::public.cefr_level,'vocabulary','Don''t ___ the chance to see the Northern Lights.',array['skip over','fail','miss','lose']::text[],'C','You miss a chance or opportunity.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:93c61feb2891','B1'::public.cefr_level,'vocabulary','The museum is ___ by public transport.',array['accessibly easy','easy accessed','hardly reachable','easily accessible']::text[],'D','''Easily accessible'' means easy to reach.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:ff9f72b5c90f','B1'::public.cefr_level,'vocabulary','I''m ___ about my exam results. I''ll know on Friday.',array['anxiety','calm','anxious','relieved']::text[],'C','Anxious means worried and nervous.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:438a2abf9f0f','B1'::public.cefr_level,'vocabulary','They ___ an agreement after hours of discussion.',array['arrived','reached','got to at','made up']::text[],'B','You reach an agreement.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:f96e37ae852c','B1'::public.cefr_level,'vocabulary','He was ___ for being late again.',array['accused','complained','criticised','blamed of']::text[],'C','To criticise is to say what someone did wrong.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:bddf1178412c','B1'::public.cefr_level,'vocabulary','Prices have ___ by 5% this year.',array['arisen','lifted','raised','risen']::text[],'D','''Rise'' (rise–rose–risen) has no object.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d8c8119e4acd','B1'::public.cefr_level,'vocabulary','The government ___ taxes last year.',array['risen','raised','arose','rose']::text[],'B','''Raise'' takes an object: raise taxes.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:3e93021585e3','B1'::public.cefr_level,'vocabulary','My suitcase was ___ — I had to pay extra at the airport.',array['oversized up','heavyweight','overloaded weight','overweight']::text[],'D','An overweight bag is heavier than allowed.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:f863fbbd392d','B1'::public.cefr_level,'vocabulary','Can you ___ me a favour and carry this box?',array['have','make','do','give']::text[],'C','We say ''do someone a favour''.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:3d6ff04b1d5e','B1'::public.cefr_level,'vocabulary','She ___ to be ill so she could stay at home.',array['intended','attended','offended','pretended']::text[],'D','To pretend is to act as if something is true when it isn''t.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:c68c3ce3f0e5','B1'::public.cefr_level,'vocabulary','The concert was a huge ___; all the tickets sold out.',array['successor','successful','success','succeed']::text[],'C','''Success'' is the noun.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:7511a19eecc1','B1'::public.cefr_level,'vocabulary','I couldn''t ___ the instructions, so I asked for help.',array['chase','follow','go after','follow on']::text[],'B','You follow instructions.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:337c41cbe62d','B1'::public.cefr_level,'vocabulary','We had a ___ time at the party — I didn''t want to leave.',array['great','large','tall','big']::text[],'A','''A great time'' means a very enjoyable time.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e9b81790a225','B1'::public.cefr_level,'vocabulary','The bridge was ___ in 1890.',array['made up','built up','built','constructed of']::text[],'C','Bridges are built.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:9ccc154d6018','B1'::public.cefr_level,'vocabulary','The teacher told the students to ___ their essays by Monday.',array['hand out','hand in','turn up','give out']::text[],'B','''Hand in'' means give work to a teacher.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:c4ca769832a4','B1'::public.cefr_level,'vocabulary','He ___ his ankle while playing football.',array['twisted','turned','bent up','wound']::text[],'A','You twist (sprain) your ankle.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:6f65f44bf3b3','B1'::public.cefr_level,'vocabulary','She was ___ to hear that she had got the job.',array['upset','disappointed','delighted','delightful']::text[],'C','Delighted means very pleased.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8e905aa91cad','B1'::public.cefr_level,'vocabulary','The village is ___ by hills on all sides.',array['surrounding','covered up','around','surrounded']::text[],'D','Surrounded means with something all around it.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e157d9a264e7','B1'::public.cefr_level,'reading','Why did Priya start volunteering?',array['Her children used the library.','She was bored after retiring.','The council asked her to.','She needed money.']::text[],'B','''Within a month, however, she was bored.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When Priya retired from teaching, she expected to enjoy a quiet life in her garden. Within a month, however, she was bored. A neighbour suggested volunteering at the local library, which was struggling to stay open after the council cut its budget. Priya now runs a homework club for children three afternoons a week and has persuaded four former colleagues to join her. ''Some of the children don''t have a quiet place to study at home,'' she explains. ''Here they get help, and the library gets more visitors, which makes it harder for the council to close it.'' Last year visitor numbers rose by a third.',null,null,null,'exam'),
  ('ai:ai-batch-06:90e97bbbf437','B1'::public.cefr_level,'reading','What problem did the library have?',array['It might have to close.','It had too many visitors.','It was too noisy.','It had no books for children.']::text[],'A','''...struggling to stay open after the council cut its budget.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When Priya retired from teaching, she expected to enjoy a quiet life in her garden. Within a month, however, she was bored. A neighbour suggested volunteering at the local library, which was struggling to stay open after the council cut its budget. Priya now runs a homework club for children three afternoons a week and has persuaded four former colleagues to join her. ''Some of the children don''t have a quiet place to study at home,'' she explains. ''Here they get help, and the library gets more visitors, which makes it harder for the council to close it.'' Last year visitor numbers rose by a third.',null,null,null,'exam'),
  ('ai:ai-batch-06:082a32b882f9','B1'::public.cefr_level,'reading','How does the homework club help the library?',array['It brings more visitors.','It replaces paid staff.','It raises money from parents.','It pays the council.']::text[],'A','''The library gets more visitors, which makes it harder for the council to close it.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When Priya retired from teaching, she expected to enjoy a quiet life in her garden. Within a month, however, she was bored. A neighbour suggested volunteering at the local library, which was struggling to stay open after the council cut its budget. Priya now runs a homework club for children three afternoons a week and has persuaded four former colleagues to join her. ''Some of the children don''t have a quiet place to study at home,'' she explains. ''Here they get help, and the library gets more visitors, which makes it harder for the council to close it.'' Last year visitor numbers rose by a third.',null,null,null,'exam'),
  ('ai:ai-batch-06:f72d69502724','B1'::public.cefr_level,'reading','Who helps Priya run the club?',array['her neighbour','the council','four former colleagues','the children''s parents']::text[],'C','''...has persuaded four former colleagues to join her.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When Priya retired from teaching, she expected to enjoy a quiet life in her garden. Within a month, however, she was bored. A neighbour suggested volunteering at the local library, which was struggling to stay open after the council cut its budget. Priya now runs a homework club for children three afternoons a week and has persuaded four former colleagues to join her. ''Some of the children don''t have a quiet place to study at home,'' she explains. ''Here they get help, and the library gets more visitors, which makes it harder for the council to close it.'' Last year visitor numbers rose by a third.',null,null,null,'exam'),
  ('ai:ai-batch-06:b507ca752f77','B1'::public.cefr_level,'reading','By how much did visitor numbers rise last year?',array['by half','by three','by 30 people','by a third']::text[],'D','''Last year visitor numbers rose by a third.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When Priya retired from teaching, she expected to enjoy a quiet life in her garden. Within a month, however, she was bored. A neighbour suggested volunteering at the local library, which was struggling to stay open after the council cut its budget. Priya now runs a homework club for children three afternoons a week and has persuaded four former colleagues to join her. ''Some of the children don''t have a quiet place to study at home,'' she explains. ''Here they get help, and the library gets more visitors, which makes it harder for the council to close it.'' Last year visitor numbers rose by a third.',null,null,null,'exam'),
  ('ai:ai-batch-06:3649995f91c3','B1'::public.cefr_level,'reading','What worried parents at first about the phone ban?',array['Their children would talk less.','Phones would be stolen from lockers.','They couldn''t contact their children in an emergency.','Students would argue more.']::text[],'C','''Parents complained that they would not be able to contact their children in an emergency.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','A secondary school in Kent has banned mobile phones during the school day, and the head teacher says the results have been surprising. Students must leave their phones in lockers when they arrive and can collect them at 3.30. At first many parents complained that they would not be able to contact their children in an emergency, so the school agreed that parents could phone the office instead. Teachers report that students now talk to each other more at lunchtime and that there have been fewer arguments that start online. Not everyone agrees, though: some older students say they should be trusted to decide for themselves.',null,null,null,'exam'),
  ('ai:ai-batch-06:efbd3632cbda','B1'::public.cefr_level,'reading','How was the parents'' problem solved?',array['Students keep phones in their bags.','Students can use phones at lunch.','The ban was cancelled.','They can phone the school office.']::text[],'D','''The school agreed that parents could phone the office instead.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','A secondary school in Kent has banned mobile phones during the school day, and the head teacher says the results have been surprising. Students must leave their phones in lockers when they arrive and can collect them at 3.30. At first many parents complained that they would not be able to contact their children in an emergency, so the school agreed that parents could phone the office instead. Teachers report that students now talk to each other more at lunchtime and that there have been fewer arguments that start online. Not everyone agrees, though: some older students say they should be trusted to decide for themselves.',null,null,null,'exam'),
  ('ai:ai-batch-06:f432ea1d4225','B1'::public.cefr_level,'reading','What change have teachers noticed?',array['Fewer arguments that start online','More students arriving late','Better exam results','Students use computers more']::text[],'A','''There have been fewer arguments that start online.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','A secondary school in Kent has banned mobile phones during the school day, and the head teacher says the results have been surprising. Students must leave their phones in lockers when they arrive and can collect them at 3.30. At first many parents complained that they would not be able to contact their children in an emergency, so the school agreed that parents could phone the office instead. Teachers report that students now talk to each other more at lunchtime and that there have been fewer arguments that start online. Not everyone agrees, though: some older students say they should be trusted to decide for themselves.',null,null,null,'exam'),
  ('ai:ai-batch-06:3aca575a467d','B1'::public.cefr_level,'reading','What do some older students think?',array['The ban should include teachers.','The day should end earlier.','They should be allowed to decide for themselves.','Lockers are not safe.']::text[],'C','''Some older students say they should be trusted to decide for themselves.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','A secondary school in Kent has banned mobile phones during the school day, and the head teacher says the results have been surprising. Students must leave their phones in lockers when they arrive and can collect them at 3.30. At first many parents complained that they would not be able to contact their children in an emergency, so the school agreed that parents could phone the office instead. Teachers report that students now talk to each other more at lunchtime and that there have been fewer arguments that start online. Not everyone agrees, though: some older students say they should be trusted to decide for themselves.',null,null,null,'exam'),
  ('ai:ai-batch-06:aa0eaf9ba93a','B1'::public.cefr_level,'reading','What did the reviewer like most about the café?',array['the view and the cakes','the fast service','the coffee','the weekend atmosphere']::text[],'A','''I''d go back for the cakes and the view.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','I had high hopes for ''The Lighthouse'', a new café on the seafront, because a friend had recommended it. The building is beautiful and the sea views are amazing, especially from the upstairs room. Unfortunately, the service didn''t match the setting. We waited twenty-five minutes for two coffees, and when they arrived, one of them was cold. The cakes, on the other hand, were delicious and reasonably priced. I''d go back for the cakes and the view, but I''d avoid weekends, when it''s clearly too busy for the staff to cope.',null,null,null,'exam'),
  ('ai:ai-batch-06:7df39230a37f','B1'::public.cefr_level,'reading','What went wrong with the coffee?',array['It was the wrong order.','They had no coffee.','It was slow and one cup was cold.','It was too expensive.']::text[],'C','''We waited twenty-five minutes... one of them was cold.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','I had high hopes for ''The Lighthouse'', a new café on the seafront, because a friend had recommended it. The building is beautiful and the sea views are amazing, especially from the upstairs room. Unfortunately, the service didn''t match the setting. We waited twenty-five minutes for two coffees, and when they arrived, one of them was cold. The cakes, on the other hand, were delicious and reasonably priced. I''d go back for the cakes and the view, but I''d avoid weekends, when it''s clearly too busy for the staff to cope.',null,null,null,'exam'),
  ('ai:ai-batch-06:c7b76dba6e0a','B1'::public.cefr_level,'reading','Why does the reviewer advise avoiding weekends?',array['The prices are higher.','The staff can''t cope with so many customers.','The view is worse.','The café is closed.']::text[],'B','''...when it''s clearly too busy for the staff to cope.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','I had high hopes for ''The Lighthouse'', a new café on the seafront, because a friend had recommended it. The building is beautiful and the sea views are amazing, especially from the upstairs room. Unfortunately, the service didn''t match the setting. We waited twenty-five minutes for two coffees, and when they arrived, one of them was cold. The cakes, on the other hand, were delicious and reasonably priced. I''d go back for the cakes and the view, but I''d avoid weekends, when it''s clearly too busy for the staff to cope.',null,null,null,'exam'),
  ('ai:ai-batch-06:6a4cd5487344','B1'::public.cefr_level,'reading','How did the reviewer hear about the café?',array['They read a review.','They saw an advert.','They walked past it.','A friend recommended it.']::text[],'D','''...because a friend had recommended it.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','I had high hopes for ''The Lighthouse'', a new café on the seafront, because a friend had recommended it. The building is beautiful and the sea views are amazing, especially from the upstairs room. Unfortunately, the service didn''t match the setting. We waited twenty-five minutes for two coffees, and when they arrived, one of them was cold. The cakes, on the other hand, were delicious and reasonably priced. I''d go back for the cakes and the view, but I''d avoid weekends, when it''s clearly too busy for the staff to cope.',null,null,null,'exam'),
  ('ai:ai-batch-06:2fe372da4cbe','B1'::public.cefr_level,'reading','What unexpected problem did Martin have when working from home?',array['He worked longer hours.','He spent more money.','He couldn''t use the internet.','His company didn''t trust him.']::text[],'A','''He found that he was working longer hours, because there was no clear end to the day.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','For ten years Martin drove forty minutes to his office in Leeds. When his company allowed staff to work from home three days a week, he thought he would save time and money. He did, but he also found that he was working longer hours, because there was no clear end to the day. He solved this by going for a walk at half past five every evening, ''pretending to come home from work''. He also joined a local choir to meet people, as he missed chatting to colleagues. Overall, he says, he would never go back to commuting every day.',null,null,null,'exam'),
  ('ai:ai-batch-06:c7a8fe1f8200','B1'::public.cefr_level,'reading','Why does Martin walk at half past five?',array['to mark the end of his working day','because his doctor told him to','to meet his colleagues','to get to the office']::text[],'A','''...pretending to come home from work.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','For ten years Martin drove forty minutes to his office in Leeds. When his company allowed staff to work from home three days a week, he thought he would save time and money. He did, but he also found that he was working longer hours, because there was no clear end to the day. He solved this by going for a walk at half past five every evening, ''pretending to come home from work''. He also joined a local choir to meet people, as he missed chatting to colleagues. Overall, he says, he would never go back to commuting every day.',null,null,null,'exam'),
  ('ai:ai-batch-06:0f848915d0f9','B1'::public.cefr_level,'reading','Why did Martin join a choir?',array['It was near his office.','He missed talking to colleagues.','He wanted to become a singer.','His company organised it.']::text[],'B','''He joined a local choir to meet people, as he missed chatting to colleagues.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','For ten years Martin drove forty minutes to his office in Leeds. When his company allowed staff to work from home three days a week, he thought he would save time and money. He did, but he also found that he was working longer hours, because there was no clear end to the day. He solved this by going for a walk at half past five every evening, ''pretending to come home from work''. He also joined a local choir to meet people, as he missed chatting to colleagues. Overall, he says, he would never go back to commuting every day.',null,null,null,'exam'),
  ('ai:ai-batch-06:462b8eba6174','B1'::public.cefr_level,'reading','What is Martin''s opinion now?',array['He works from home every day.','He wants to commute every day again.','He wants to change jobs.','He prefers working partly from home.']::text[],'D','''He would never go back to commuting every day.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','For ten years Martin drove forty minutes to his office in Leeds. When his company allowed staff to work from home three days a week, he thought he would save time and money. He did, but he also found that he was working longer hours, because there was no clear end to the day. He solved this by going for a walk at half past five every evening, ''pretending to come home from work''. He also joined a local choir to meet people, as he missed chatting to colleagues. Overall, he says, he would never go back to commuting every day.',null,null,null,'exam'),
  ('ai:ai-batch-06:de3d5f380715','B1'::public.cefr_level,'reading','Where should plastic bottles go?',array['in the blue bin','in the brown container','in the black bin','in the green bin']::text[],'A','''The blue bin for paper, cans and plastic bottles.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','From next month, households in the town will receive three bins instead of two. The green bin will be for garden waste, the blue bin for paper, cans and plastic bottles, and the black bin for everything else. Food waste must now go in a small brown container, which will be collected every week. Black bins will be emptied every two weeks rather than weekly. The council says the changes will save money and increase recycling, but some residents are worried that bins will smell in the summer.',null,null,null,'exam'),
  ('ai:ai-batch-06:dfc1d076f64c','B1'::public.cefr_level,'reading','How often will black bins be emptied?',array['every week','every two weeks','every month','twice a week']::text[],'B','''Black bins will be emptied every two weeks rather than weekly.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','From next month, households in the town will receive three bins instead of two. The green bin will be for garden waste, the blue bin for paper, cans and plastic bottles, and the black bin for everything else. Food waste must now go in a small brown container, which will be collected every week. Black bins will be emptied every two weeks rather than weekly. The council says the changes will save money and increase recycling, but some residents are worried that bins will smell in the summer.',null,null,null,'exam'),
  ('ai:ai-batch-06:eb796f45c5cb','B1'::public.cefr_level,'reading','What are some residents worried about?',array['not having enough bins','bins smelling in summer','losing their gardens','paying more tax']::text[],'B','''Some residents are worried that bins will smell in the summer.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','From next month, households in the town will receive three bins instead of two. The green bin will be for garden waste, the blue bin for paper, cans and plastic bottles, and the black bin for everything else. Food waste must now go in a small brown container, which will be collected every week. Black bins will be emptied every two weeks rather than weekly. The council says the changes will save money and increase recycling, but some residents are worried that bins will smell in the summer.',null,null,null,'exam'),
  ('ai:ai-batch-06:17295b943718','B1'::public.cefr_level,'reading','Which waste is collected every week?',array['garden waste','everything in the black bin','food waste','paper']::text[],'C','''Food waste... will be collected every week.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','From next month, households in the town will receive three bins instead of two. The green bin will be for garden waste, the blue bin for paper, cans and plastic bottles, and the black bin for everything else. Food waste must now go in a small brown container, which will be collected every week. Black bins will be emptied every two weeks rather than weekly. The council says the changes will save money and increase recycling, but some residents are worried that bins will smell in the summer.',null,null,null,'exam'),
  ('ai:ai-batch-06:c9b93ee27885','B1'::public.cefr_level,'reading','Why did Leah start baking at night?',array['She was studying in the day.','She could use her aunt''s kitchen then.','She worked in a café in the day.','Markets open at night.']::text[],'B','''My aunt let me use her kitchen at night.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Interviewer: You started your bakery when you were only nineteen. Wasn''t that risky? — Leah: Of course. I''d failed my exams and didn''t know what to do, so my aunt let me use her kitchen at night. I sold bread at a market on Saturdays. — Interviewer: When did you realise it could be a real business? — Leah: When a café asked me to supply them every day. I couldn''t do it alone, so I took a loan and rented a small shop. — Interviewer: Any advice for young people? — Leah: Don''t wait until everything is perfect. Start small and learn from your mistakes.',null,null,null,'exam'),
  ('ai:ai-batch-06:48f98e79e8a8','B1'::public.cefr_level,'reading','What made Leah think her bakery could be a real business?',array['She passed her exams.','A café wanted bread every day.','She won a prize at the market.','Her aunt gave her money.']::text[],'B','''When a café asked me to supply them every day.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Interviewer: You started your bakery when you were only nineteen. Wasn''t that risky? — Leah: Of course. I''d failed my exams and didn''t know what to do, so my aunt let me use her kitchen at night. I sold bread at a market on Saturdays. — Interviewer: When did you realise it could be a real business? — Leah: When a café asked me to supply them every day. I couldn''t do it alone, so I took a loan and rented a small shop. — Interviewer: Any advice for young people? — Leah: Don''t wait until everything is perfect. Start small and learn from your mistakes.',null,null,null,'exam'),
  ('ai:ai-batch-06:5ac22ae7ee60','B1'::public.cefr_level,'reading','How did Leah pay for the shop?',array['She used her savings from school.','Her aunt paid.','The café paid.','She borrowed money.']::text[],'D','''I took a loan and rented a small shop.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Interviewer: You started your bakery when you were only nineteen. Wasn''t that risky? — Leah: Of course. I''d failed my exams and didn''t know what to do, so my aunt let me use her kitchen at night. I sold bread at a market on Saturdays. — Interviewer: When did you realise it could be a real business? — Leah: When a café asked me to supply them every day. I couldn''t do it alone, so I took a loan and rented a small shop. — Interviewer: Any advice for young people? — Leah: Don''t wait until everything is perfect. Start small and learn from your mistakes.',null,null,null,'exam'),
  ('ai:ai-batch-06:f0171851d66f','B1'::public.cefr_level,'reading','What is Leah''s advice?',array['Start small instead of waiting for perfection.','Never borrow money.','Always finish your exams first.','Work alone at the beginning.']::text[],'A','''Don''t wait until everything is perfect. Start small...''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Interviewer: You started your bakery when you were only nineteen. Wasn''t that risky? — Leah: Of course. I''d failed my exams and didn''t know what to do, so my aunt let me use her kitchen at night. I sold bread at a market on Saturdays. — Interviewer: When did you realise it could be a real business? — Leah: When a café asked me to supply them every day. I couldn''t do it alone, so I took a loan and rented a small shop. — Interviewer: Any advice for young people? — Leah: Don''t wait until everything is perfect. Start small and learn from your mistakes.',null,null,null,'exam'),
  ('ai:ai-batch-06:938df57dea16','B1'::public.cefr_level,'reading','What makes the Fringe different from many festivals?',array['There is no committee choosing who performs.','It happens in several cities.','All the shows are free.','It only has famous performers.']::text[],'A','''It has no selection committee: anyone with a venue can take part.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','The Edinburgh Festival Fringe takes place every August and is often described as the largest arts festival in the world. Unlike many festivals, it has no selection committee: anyone with a venue can take part, which means that famous comedians perform alongside students putting on their first show. This openness is part of its charm, but it also means quality varies enormously. Many performers lose money, because venues are expensive and tickets for unknown shows can be hard to sell. Even so, people keep coming back, hoping to be discovered.',null,null,null,'exam'),
  ('ai:ai-batch-06:b50dfbd57207','B1'::public.cefr_level,'reading','What is a disadvantage of the Fringe''s openness?',array['Tickets are very expensive.','The quality of shows varies a lot.','There are too few venues.','Famous comedians don''t come.']::text[],'B','''...it also means quality varies enormously.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','The Edinburgh Festival Fringe takes place every August and is often described as the largest arts festival in the world. Unlike many festivals, it has no selection committee: anyone with a venue can take part, which means that famous comedians perform alongside students putting on their first show. This openness is part of its charm, but it also means quality varies enormously. Many performers lose money, because venues are expensive and tickets for unknown shows can be hard to sell. Even so, people keep coming back, hoping to be discovered.',null,null,null,'exam'),
  ('ai:ai-batch-06:2050950a2270','B1'::public.cefr_level,'reading','Why do many performers lose money?',array['They have to pay the committee.','The festival is too short.','Audiences only see free shows.','Venues are expensive and tickets are hard to sell.']::text[],'D','''Venues are expensive and tickets for unknown shows can be hard to sell.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','The Edinburgh Festival Fringe takes place every August and is often described as the largest arts festival in the world. Unlike many festivals, it has no selection committee: anyone with a venue can take part, which means that famous comedians perform alongside students putting on their first show. This openness is part of its charm, but it also means quality varies enormously. Many performers lose money, because venues are expensive and tickets for unknown shows can be hard to sell. Even so, people keep coming back, hoping to be discovered.',null,null,null,'exam'),
  ('ai:ai-batch-06:2c060598d917','B1'::public.cefr_level,'reading','Why do performers keep coming back?',array['They are paid by the festival.','They hope to be discovered.','They have to by law.','They always make money.']::text[],'B','''People keep coming back, hoping to be discovered.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','The Edinburgh Festival Fringe takes place every August and is often described as the largest arts festival in the world. Unlike many festivals, it has no selection committee: anyone with a venue can take part, which means that famous comedians perform alongside students putting on their first show. This openness is part of its charm, but it also means quality varies enormously. Many performers lose money, because venues are expensive and tickets for unknown shows can be hard to sell. Even so, people keep coming back, hoping to be discovered.',null,null,null,'exam'),
  ('ai:ai-batch-06:6f84073cb3c3','B1'::public.cefr_level,'reading','When does the Fringe take place?',array['every summer and winter','every two years','in spring','every August']::text[],'D','''The Edinburgh Festival Fringe takes place every August.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','The Edinburgh Festival Fringe takes place every August and is often described as the largest arts festival in the world. Unlike many festivals, it has no selection committee: anyone with a venue can take part, which means that famous comedians perform alongside students putting on their first show. This openness is part of its charm, but it also means quality varies enormously. Many performers lose money, because venues are expensive and tickets for unknown shows can be hard to sell. Even so, people keep coming back, hoping to be discovered.',null,null,null,'exam'),
  ('ai:ai-batch-06:697f291b0c54','B1'::public.cefr_level,'reading','When can students collect their phones?',array['in an emergency','at lunchtime','at 3.30','when they arrive']::text[],'C','''...can collect them at 3.30.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','A secondary school in Kent has banned mobile phones during the school day, and the head teacher says the results have been surprising. Students must leave their phones in lockers when they arrive and can collect them at 3.30. At first many parents complained that they would not be able to contact their children in an emergency, so the school agreed that parents could phone the office instead. Teachers report that students now talk to each other more at lunchtime and that there have been fewer arguments that start online. Not everyone agrees, though: some older students say they should be trusted to decide for themselves.',null,null,null,'exam'),
  ('ai:ai-batch-06:2274be4c49fb','B1'::public.cefr_level,'reading','How long did Martin''s drive to work take?',array['ten minutes','forty minutes','three hours','half an hour']::text[],'B','''For ten years Martin drove forty minutes to his office.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','For ten years Martin drove forty minutes to his office in Leeds. When his company allowed staff to work from home three days a week, he thought he would save time and money. He did, but he also found that he was working longer hours, because there was no clear end to the day. He solved this by going for a walk at half past five every evening, ''pretending to come home from work''. He also joined a local choir to meet people, as he missed chatting to colleagues. Overall, he says, he would never go back to commuting every day.',null,null,null,'exam'),
  ('ai:ai-batch-06:283ae452b7cf','B1'::public.cefr_level,'reading','What was Priya''s job before she retired?',array['council worker','teacher','gardener','librarian']::text[],'B','''When Priya retired from teaching...''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','When Priya retired from teaching, she expected to enjoy a quiet life in her garden. Within a month, however, she was bored. A neighbour suggested volunteering at the local library, which was struggling to stay open after the council cut its budget. Priya now runs a homework club for children three afternoons a week and has persuaded four former colleagues to join her. ''Some of the children don''t have a quiet place to study at home,'' she explains. ''Here they get help, and the library gets more visitors, which makes it harder for the council to close it.'' Last year visitor numbers rose by a third.',null,null,null,'exam'),
  ('ai:ai-batch-06:9c5f28509cb9','B1'::public.cefr_level,'reading','Which part of the café has the best views?',array['the terrace','the ground floor','the kitchen','the upstairs room']::text[],'D','''...especially from the upstairs room.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','I had high hopes for ''The Lighthouse'', a new café on the seafront, because a friend had recommended it. The building is beautiful and the sea views are amazing, especially from the upstairs room. Unfortunately, the service didn''t match the setting. We waited twenty-five minutes for two coffees, and when they arrived, one of them was cold. The cakes, on the other hand, were delicious and reasonably priced. I''d go back for the cakes and the view, but I''d avoid weekends, when it''s clearly too busy for the staff to cope.',null,null,null,'exam'),
  ('ai:ai-batch-06:5a5a45b58f37','B1'::public.cefr_level,'grammar','I ___ to the dentist since last year. I must make an appointment.',array['didn''t go','haven''t been','wasn''t','don''t go']::text[],'B','From the past until now with ''since'': present perfect.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:b14a266c969e','B1'::public.cefr_level,'grammar','He apologised ___ breaking the window.',array['about','for','to','of']::text[],'B','We apologise for something.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:b7a833c3729e','B1'::public.cefr_level,'grammar','If you ___ me, what would you do?',array['will be','are','were','would be']::text[],'C','Giving advice: ''If I were you / If you were me''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a7d3dfe6355c','B1'::public.cefr_level,'grammar','She ___ have left already — her coat has gone.',array['would','must','can''t','should']::text[],'B','''Must have'' = logical certainty about the past.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e8cce565efb5','B1'::public.cefr_level,'vocabulary','Can you ___ for my plants while I''m away?',array['look after','look up','look into','look for']::text[],'A','''Look after'' means take care of.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:2b475275a8ea','B1'::public.cefr_level,'vocabulary','I ran ___ of milk, so I had black coffee.',array['away','out','over','off']::text[],'B','''Run out of'' means have none left.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d82c4d35e4a9','B1'::public.cefr_level,'vocabulary','The children ___ up the toys and put them in the box.',array['got','picked','lifted on','took']::text[],'B','''Pick up'' means lift from the ground.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:1ff4df3f850f','B1'::public.cefr_level,'vocabulary','He finally ___ up the courage to ask her out.',array['made','plucked','took on','pulled']::text[],'B','''Pluck up the courage'' means find the courage.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:52b9a2e92b3c','B2'::public.cefr_level,'grammar','Had I known about the traffic, I ___ earlier.',array['would leave','will have left','had left','would have left']::text[],'D','Inverted third conditional: Had I known... = If I had known...',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:712dccf437bf','B2'::public.cefr_level,'grammar','He admitted ___ the documents without permission.',array['to have copy','to copy','copy','having copied']::text[],'D','''Admit'' is followed by -ing (here the perfect -ing form).',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:20f2f8e7bb59','B2'::public.cefr_level,'grammar','The project, ___ was finished on time, won an award.',array['which','what','who','that']::text[],'A','Non-defining relative clauses use ''which'', not ''that''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:eb330c250265','B2'::public.cefr_level,'grammar','I''d rather you ___ tell anyone about this yet.',array['didn''t','won''t','not','don''t']::text[],'A','''I''d rather + subject + past simple'' for preferences about others.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:f1706402c032','B2'::public.cefr_level,'grammar','No sooner had we arrived ___ it started to rain.',array['then','that','than','when']::text[],'C','The pattern is ''No sooner... than''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:adef6080d79c','B2'::public.cefr_level,'grammar','He is thought ___ the country last week.',array['to leave','to have left','leaving','that he left']::text[],'B','Passive reporting about the past: ''to have + past participle''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d6a136fbd42c','B2'::public.cefr_level,'grammar','If he hadn''t missed the bus, he ___ here now.',array['will be','would be','had been','would have been']::text[],'B','Mixed conditional: past condition, present result.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a66e1c43db7e','B2'::public.cefr_level,'grammar','By the end of the year, she ___ for the company for a decade.',array['is working','will have been working','has worked','will work']::text[],'B','Future perfect continuous for duration up to a future point.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:2defda9e1ae8','B2'::public.cefr_level,'grammar','Rarely ___ such a beautiful sunset.',array['I have seen','I saw','have I seen','did I saw']::text[],'C','After a negative adverb at the start, we invert.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:6d46c54ce0c7','B2'::public.cefr_level,'grammar','You needn''t ___ a taxi; I could have driven you.',array['take','taken','have taken','to take']::text[],'C','''Needn''t have + past participle'' = it was done but wasn''t necessary.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:2df0338febff','B2'::public.cefr_level,'grammar','It''s high time the council ___ something about the potholes.',array['does','did','will do','do']::text[],'B','''It''s high time + past simple''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:f4c95f34923f','B2'::public.cefr_level,'grammar','Not until I got home ___ that I''d lost my wallet.',array['I did realise','did I realise','I realised','realised I']::text[],'B','''Not until...'' at the start causes inversion in the main clause.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8781408b4d2f','B2'::public.cefr_level,'grammar','She spoke quietly so as ___ wake the baby.',array['not to','to not','don''t','not']::text[],'A','''So as not to'' expresses a negative purpose.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a1a4f2595a94','B2'::public.cefr_level,'grammar','He insisted ___ paying for dinner.',array['at','on','in','to']::text[],'B','''Insist on'' + -ing.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d25e5ba5c318','B2'::public.cefr_level,'grammar','The documents are ___ to be signed by Friday.',array['due','planned','supposed by','expect']::text[],'A','''Be due to'' means expected or scheduled.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:80d268676771','B2'::public.cefr_level,'grammar','Whatever ___, don''t open the door.',array['happened','happens','will happen','happen']::text[],'B','''Whatever happens'' + imperative.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:76b463d606ee','B2'::public.cefr_level,'grammar','I''m not used ___ such cold weather.',array['at','to','for','with']::text[],'B','''Be used to'' + noun/-ing.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:6c483524b461','B2'::public.cefr_level,'grammar','The suspect is believed ___ in the area.',array['hiding','that hides','to hide','to be hiding']::text[],'D','Reporting passive with a continuous infinitive for an ongoing action.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8f0d97f940df','B2'::public.cefr_level,'grammar','___ the bad reviews, the film was a box-office hit.',array['However','Even though','Although','In spite of']::text[],'D','''In spite of'' + noun phrase.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e8ac4fcde9aa','B2'::public.cefr_level,'grammar','She has two brothers, neither of ___ lives nearby.',array['which','who','them','whom']::text[],'D','After a preposition in a relative clause, ''whom'' refers to people.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:f57486e739ba','B2'::public.cefr_level,'grammar','I would appreciate it if you ___ reply by Monday.',array['will','should be','could','can']::text[],'C','Polite requests: ''I''d appreciate it if you could...''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e633265e13e4','B2'::public.cefr_level,'grammar','The more I learn about it, ___ confused I become.',array['the more','more','the most','most']::text[],'A','''The + comparative..., the + comparative''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a4273dd0baab','B2'::public.cefr_level,'grammar','Only by working together ___ solve this problem.',array['we will','we can','can we','we could to']::text[],'C','''Only by...'' at the start causes inversion.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:30d914f4d9c7','B2'::public.cefr_level,'grammar','He might ___ the message; he hasn''t replied.',array['not receive','not received','have not receive','not have received']::text[],'D','''Might not have + past participle'' = possibly didn''t happen.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:2e5189ee3f34','B2'::public.cefr_level,'grammar','The bridge ___ when the storm hit, so it collapsed.',array['had repaired','is being repaired','was being repaired','was repaired']::text[],'C','Past continuous passive: an action in progress in the past.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:6464796b84f2','B2'::public.cefr_level,'grammar','Supposing you ___ the lottery, what would you buy first?',array['win','had won','will win','won']::text[],'D','''Supposing'' + past simple for imaginary situations.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:10f621cbf731','B2'::public.cefr_level,'grammar','There''s no need ___ — we''ve got plenty of time.',array['for hurry','to hurry','hurrying','hurry']::text[],'B','''There''s no need to + verb''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8477bf5ef76d','B2'::public.cefr_level,'grammar','I regret ___ you that your application was unsuccessful.',array['to inform','inform','informing','to have informing']::text[],'A','''Regret to inform'' is formal for giving bad news.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:ee3fb1e60300','B2'::public.cefr_level,'grammar','I regret ___ to university; I wish I had.',array['not going','not to go','don''t go','to not go']::text[],'A','''Regret + -ing'' refers to past actions.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
