  ('ai:ai-batch-06:bbfbe4a94a2c','C1'::public.cefr_level,'vocabulary','The two accounts of the meeting ___ in several important respects.',array['divulge','divert','digress','diverge']::text[],'D','To diverge is to differ.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
