  ('ai:ai-batch-06:b8f2811aa022','C1'::public.cefr_level,'vocabulary','The council has ___ plans to build on the green belt.',array['shelved','sheltered','shoved','shell']::text[],'A','To shelve plans is to postpone or abandon them.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
