  ('ai:ai-batch-06:c323273a209b','C2'::public.cefr_level,'vocabulary','The debate quickly ___ into personal insults.',array['designated','generated','degenerated','delegated']::text[],'C','To degenerate = to become worse.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:53be90c4a29a','C2'::public.cefr_level,'vocabulary','His argument rests on a number of ___ assumptions.',array['questionable','questioned at','questionnaire','questioning']::text[],'A','Questionable = doubtful.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:82800fbf5a76','C2'::public.cefr_level,'vocabulary','She delivered a ___ critique of the government''s policy.',array['scalding of','scheming','scintillating','scathing']::text[],'D','Scathing = severely critical.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e6cd1bffde21','C2'::public.cefr_level,'vocabulary','The new regulations will be ___ in over the next two years.',array['phrased','phased','faced','fazed']::text[],'B','''Phase in'' = introduce gradually.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:7d55d0811836','C2'::public.cefr_level,'vocabulary','The author ___ the reader with a series of unexpected twists.',array['misfoots','wrong-headed','wrong-foots','mistreads']::text[],'C','To wrong-foot = to put someone at a disadvantage by surprise.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:712a080338af','C2'::public.cefr_level,'vocabulary','The committee''s findings were ___ in their condemnation.',array['unequalled','unequivocally','unequivocal','unequal']::text[],'C','Unequivocal = completely clear, without doubt.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:c16ba40dec71','C2'::public.cefr_level,'vocabulary','His ___ manner made him popular with colleagues.',array['effable','affordable','affable','affluent']::text[],'C','Affable = friendly and easy to talk to.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:9a32a79c3520','C2'::public.cefr_level,'vocabulary','The plan was ___ from the start by a lack of funding.',array['handstrung','hamshackled','hamstringed','hamstrung']::text[],'D','Hamstrung = severely restricted.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:c04593095ba6','C2'::public.cefr_level,'vocabulary','The essay offers a ___ analysis of a complex subject.',array['cogitated','cognate','coherent with','cogent']::text[],'D','Cogent = clear, logical and convincing.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:034f9763fd71','C2'::public.cefr_level,'vocabulary','The company was ___ by a series of lawsuits.',array['beguiled','belittled','belied','beleaguered']::text[],'D','Beleaguered = in a very difficult situation.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:5ce8a7a53d5d','C2'::public.cefr_level,'vocabulary','The novel has been ___ as the finest of its generation.',array['lauded','lorded','loaded','laundered']::text[],'A','Lauded = highly praised.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e7e11c218130','C2'::public.cefr_level,'vocabulary','There was a ___ of truth in what he said.',array['kennel','kernel','colonel','cornel']::text[],'B','''A kernel of truth'' = a small amount of truth.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:3c14d3e8981b','C2'::public.cefr_level,'vocabulary','The proposal is ___ with practical difficulties.',array['fraught','fought','freighted','frayed']::text[],'A','''Fraught with'' = full of (problems).',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:8040115fe879','C2'::public.cefr_level,'vocabulary','She made an ___ attempt to hide her disappointment.',array['ill-gotten','ill-concealed','ill-conceived of','ill-fated']::text[],'B','An ill-concealed feeling is badly hidden.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:28466a76a258','C2'::public.cefr_level,'reading','What does the writer say about historical complaints about new media?',array['Novels were always admired.','Each new medium was accused of harming thought.','Radio improved concentration.','Only smartphones have been criticised.']::text[],'B','''Each new medium... was accused in its day of corrupting the young and fragmenting thought.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','It has become something of a commonplace to lament the decline of attention, as though our capacity for sustained concentration were a natural resource being depleted by smartphones. The historical record complicates this narrative. Each new medium, from the novel to the radio, was accused in its day of corrupting the young and fragmenting thought. This is not to dismiss present concerns as mere moral panic; the business models of many digital platforms are explicitly predicated on capturing and monetising attention, which was not true of the eighteenth-century novel. Yet framing the problem as one of individual willpower risks obscuring its structural character, and places the burden of resistance on users rather than on the design choices that shape their behaviour.',null,null,null,'exam'),
  ('ai:ai-batch-06:3039b626784d','C2'::public.cefr_level,'reading','How, according to the writer, are digital platforms different from the novel?',array['Their business models depend on capturing attention.','They are not commercial.','They are read by fewer people.','They are older.']::text[],'A','''The business models of many digital platforms are explicitly predicated on capturing and monetising attention.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','It has become something of a commonplace to lament the decline of attention, as though our capacity for sustained concentration were a natural resource being depleted by smartphones. The historical record complicates this narrative. Each new medium, from the novel to the radio, was accused in its day of corrupting the young and fragmenting thought. This is not to dismiss present concerns as mere moral panic; the business models of many digital platforms are explicitly predicated on capturing and monetising attention, which was not true of the eighteenth-century novel. Yet framing the problem as one of individual willpower risks obscuring its structural character, and places the burden of resistance on users rather than on the design choices that shape their behaviour.',null,null,null,'exam'),
  ('ai:ai-batch-06:01da8c8031fd','C2'::public.cefr_level,'reading','What risk does the writer see in framing the issue as individual willpower?',array['It increases moral panic.','It hides the role of design and places the burden on users.','It makes people lazier.','It makes platforms illegal.']::text[],'B','''...risks obscuring its structural character, and places the burden of resistance on users.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','It has become something of a commonplace to lament the decline of attention, as though our capacity for sustained concentration were a natural resource being depleted by smartphones. The historical record complicates this narrative. Each new medium, from the novel to the radio, was accused in its day of corrupting the young and fragmenting thought. This is not to dismiss present concerns as mere moral panic; the business models of many digital platforms are explicitly predicated on capturing and monetising attention, which was not true of the eighteenth-century novel. Yet framing the problem as one of individual willpower risks obscuring its structural character, and places the burden of resistance on users rather than on the design choices that shape their behaviour.',null,null,null,'exam'),
  ('ai:ai-batch-06:b8f5dc12ae94','C2'::public.cefr_level,'reading','What is the writer''s attitude to present concerns about attention?',array['They are pure moral panic.','They are exaggerated by scientists.','They are partly valid but often misframed.','They are entirely new and unprecedented.']::text[],'C','''This is not to dismiss present concerns...'' but framing them as willpower is misleading.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','It has become something of a commonplace to lament the decline of attention, as though our capacity for sustained concentration were a natural resource being depleted by smartphones. The historical record complicates this narrative. Each new medium, from the novel to the radio, was accused in its day of corrupting the young and fragmenting thought. This is not to dismiss present concerns as mere moral panic; the business models of many digital platforms are explicitly predicated on capturing and monetising attention, which was not true of the eighteenth-century novel. Yet framing the problem as one of individual willpower risks obscuring its structural character, and places the burden of resistance on users rather than on the design choices that shape their behaviour.',null,null,null,'exam'),
  ('ai:ai-batch-06:1c4dd6ebee8f','C2'::public.cefr_level,'reading','What does ''predicated on'' mean in the text?',array['independent of','predicting','based on','opposed to']::text[],'C','''Predicated on capturing attention'' = based on it.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','It has become something of a commonplace to lament the decline of attention, as though our capacity for sustained concentration were a natural resource being depleted by smartphones. The historical record complicates this narrative. Each new medium, from the novel to the radio, was accused in its day of corrupting the young and fragmenting thought. This is not to dismiss present concerns as mere moral panic; the business models of many digital platforms are explicitly predicated on capturing and monetising attention, which was not true of the eighteenth-century novel. Yet framing the problem as one of individual willpower risks obscuring its structural character, and places the burden of resistance on users rather than on the design choices that shape their behaviour.',null,null,null,'exam'),
  ('ai:ai-batch-06:284736aaee55','C2'::public.cefr_level,'reading','According to the text, what do monuments often reveal most about?',array['the sculptors'' techniques','the people who commissioned them','the people they depict','the cities they stand in']::text[],'B','Monuments ''frequently tell us more about those who commissioned them than about those they depict.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Debates over contested statues often founder on a false dichotomy between preserving history and erasing it. Monuments are not history itself but interpretations of it, erected at particular moments to convey particular values, and frequently tell us more about those who commissioned them than about those they depict. Removing a statue to a museum, where it can be contextualised, is arguably less an act of erasure than of reclassification. Conversely, insisting that every monument remain untouched presupposes that the judgements of one generation should bind all those that follow — a position that would seem odd if applied to any other public decision.',null,null,null,'exam'),
  ('ai:ai-batch-06:04606e6a16a0','C2'::public.cefr_level,'reading','How does the writer describe moving a statue to a museum?',array['as reclassification rather than erasure','as destroying history','as illegal','as too expensive']::text[],'A','''...arguably less an act of erasure than of reclassification.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Debates over contested statues often founder on a false dichotomy between preserving history and erasing it. Monuments are not history itself but interpretations of it, erected at particular moments to convey particular values, and frequently tell us more about those who commissioned them than about those they depict. Removing a statue to a museum, where it can be contextualised, is arguably less an act of erasure than of reclassification. Conversely, insisting that every monument remain untouched presupposes that the judgements of one generation should bind all those that follow — a position that would seem odd if applied to any other public decision.',null,null,null,'exam'),
  ('ai:ai-batch-06:6eeeb3216245','C2'::public.cefr_level,'reading','What does the writer find odd about keeping every monument untouched?',array['It ignores museums'' opinions.','It costs too much money.','It lets one generation''s judgements bind all later ones.','It removes history from schools.']::text[],'C','''...presupposes that the judgements of one generation should bind all those that follow.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Debates over contested statues often founder on a false dichotomy between preserving history and erasing it. Monuments are not history itself but interpretations of it, erected at particular moments to convey particular values, and frequently tell us more about those who commissioned them than about those they depict. Removing a statue to a museum, where it can be contextualised, is arguably less an act of erasure than of reclassification. Conversely, insisting that every monument remain untouched presupposes that the judgements of one generation should bind all those that follow — a position that would seem odd if applied to any other public decision.',null,null,null,'exam'),
  ('ai:ai-batch-06:cc409277e789','C2'::public.cefr_level,'reading','What ''false dichotomy'' does the writer identify?',array['art versus politics','preserving history versus erasing it','museums versus galleries','old versus new statues']::text[],'B','Debates ''founder on a false dichotomy between preserving history and erasing it.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Debates over contested statues often founder on a false dichotomy between preserving history and erasing it. Monuments are not history itself but interpretations of it, erected at particular moments to convey particular values, and frequently tell us more about those who commissioned them than about those they depict. Removing a statue to a museum, where it can be contextualised, is arguably less an act of erasure than of reclassification. Conversely, insisting that every monument remain untouched presupposes that the judgements of one generation should bind all those that follow — a position that would seem odd if applied to any other public decision.',null,null,null,'exam'),
  ('ai:ai-batch-06:06c691a67c0a','C2'::public.cefr_level,'reading','What do surveys suggest about trust in expertise?',array['Doctors are trusted least.','Trust in all experts has collapsed.','Journalists are trusted most.','Trust varies: scientists are trusted more than politicians.']::text[],'D','''Confidence in scientists and doctors remains comparatively high, while trust in politicians and journalists is markedly lower.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Public trust in expertise is sometimes portrayed as having collapsed, but surveys suggest a more nuanced picture: confidence in scientists and doctors remains comparatively high, while trust in politicians and journalists is markedly lower. What appears to have eroded is less faith in knowledge per se than deference to institutions perceived as remote or self-serving. Experts who acknowledge uncertainty openly, paradoxically, may command more durable trust than those who project unwarranted certainty, since the latter are exposed when, as is inevitable in fast-moving situations, initial advice has to be revised.',null,null,null,'exam'),
  ('ai:ai-batch-06:3964cd3a983c','C2'::public.cefr_level,'reading','What, according to the writer, has eroded?',array['faith in knowledge itself','deference to institutions seen as remote or self-serving','the number of experts','interest in science']::text[],'B','''Less faith in knowledge per se than deference to institutions perceived as remote or self-serving.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Public trust in expertise is sometimes portrayed as having collapsed, but surveys suggest a more nuanced picture: confidence in scientists and doctors remains comparatively high, while trust in politicians and journalists is markedly lower. What appears to have eroded is less faith in knowledge per se than deference to institutions perceived as remote or self-serving. Experts who acknowledge uncertainty openly, paradoxically, may command more durable trust than those who project unwarranted certainty, since the latter are exposed when, as is inevitable in fast-moving situations, initial advice has to be revised.',null,null,null,'exam'),
  ('ai:ai-batch-06:c43436541f83','C2'::public.cefr_level,'reading','Why might experts who admit uncertainty be trusted more in the long run?',array['They never change their advice.','They are more famous.','They are not exposed when advice changes.','They give simpler advice.']::text[],'C','Overconfident experts ''are exposed when... initial advice has to be revised.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Public trust in expertise is sometimes portrayed as having collapsed, but surveys suggest a more nuanced picture: confidence in scientists and doctors remains comparatively high, while trust in politicians and journalists is markedly lower. What appears to have eroded is less faith in knowledge per se than deference to institutions perceived as remote or self-serving. Experts who acknowledge uncertainty openly, paradoxically, may command more durable trust than those who project unwarranted certainty, since the latter are exposed when, as is inevitable in fast-moving situations, initial advice has to be revised.',null,null,null,'exam'),
  ('ai:ai-batch-06:5d7382f57e25','C2'::public.cefr_level,'reading','What does ''per se'' mean in the text?',array['by chance','in Latin','for each person','in itself']::text[],'D','''Faith in knowledge per se'' = in knowledge as such.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Public trust in expertise is sometimes portrayed as having collapsed, but surveys suggest a more nuanced picture: confidence in scientists and doctors remains comparatively high, while trust in politicians and journalists is markedly lower. What appears to have eroded is less faith in knowledge per se than deference to institutions perceived as remote or self-serving. Experts who acknowledge uncertainty openly, paradoxically, may command more durable trust than those who project unwarranted certainty, since the latter are exposed when, as is inevitable in fast-moving situations, initial advice has to be revised.',null,null,null,'exam'),
  ('ai:ai-batch-06:cf2957698720','C2'::public.cefr_level,'reading','What was Swift''s complaint mentioned in the text?',array['the word ''reliable''','spelling reform','foreign words','the introduction of abbreviations like ''mob''']::text[],'D','''Jonathan Swift lamented the introduction of abbreviations such as ''mob''.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Complaints about the degeneration of English are almost as old as the language itself. Jonathan Swift lamented the introduction of abbreviations such as ''mob''; later commentators deplored ''reliable'' as an ugly hybrid. What such complaints tend to overlook is that change is not decay but the normal condition of every living language, and that today''s solecism is frequently tomorrow''s standard usage. Linguists are not, however, indifferent to how language is used; their objection is to the conflation of prestige with correctness, whereby the habits of a particular social group are presented as the logical rules of the language.',null,null,null,'exam'),
  ('ai:ai-batch-06:7eca96d0c28a','C2'::public.cefr_level,'reading','What is the linguists'' main objection, according to the text?',array['The teaching of grammar','Any change to language','People using slang','Confusing prestige with correctness']::text[],'D','''Their objection is to the conflation of prestige with correctness.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Complaints about the degeneration of English are almost as old as the language itself. Jonathan Swift lamented the introduction of abbreviations such as ''mob''; later commentators deplored ''reliable'' as an ugly hybrid. What such complaints tend to overlook is that change is not decay but the normal condition of every living language, and that today''s solecism is frequently tomorrow''s standard usage. Linguists are not, however, indifferent to how language is used; their objection is to the conflation of prestige with correctness, whereby the habits of a particular social group are presented as the logical rules of the language.',null,null,null,'exam'),
  ('ai:ai-batch-06:99394448cb34','C2'::public.cefr_level,'reading','What does ''today''s solecism is frequently tomorrow''s standard usage'' mean?',array['What is considered an error now often becomes accepted later.','Errors are never accepted.','Old words always disappear.','Standard English never changes.']::text[],'A','A solecism is an error; the sentence says errors often become standard.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Complaints about the degeneration of English are almost as old as the language itself. Jonathan Swift lamented the introduction of abbreviations such as ''mob''; later commentators deplored ''reliable'' as an ugly hybrid. What such complaints tend to overlook is that change is not decay but the normal condition of every living language, and that today''s solecism is frequently tomorrow''s standard usage. Linguists are not, however, indifferent to how language is used; their objection is to the conflation of prestige with correctness, whereby the habits of a particular social group are presented as the logical rules of the language.',null,null,null,'exam'),
  ('ai:ai-batch-06:d61de608b6bf','C2'::public.cefr_level,'reading','What is the writer''s view of language change?',array['It is a sign of decline.','It should be prevented by law.','It is normal, not decay.','It only affects spoken English.']::text[],'C','''Change is not decay but the normal condition of every living language.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Complaints about the degeneration of English are almost as old as the language itself. Jonathan Swift lamented the introduction of abbreviations such as ''mob''; later commentators deplored ''reliable'' as an ugly hybrid. What such complaints tend to overlook is that change is not decay but the normal condition of every living language, and that today''s solecism is frequently tomorrow''s standard usage. Linguists are not, however, indifferent to how language is used; their objection is to the conflation of prestige with correctness, whereby the habits of a particular social group are presented as the logical rules of the language.',null,null,null,'exam'),
  ('ai:ai-batch-06:5c529deb6fb1','C2'::public.cefr_level,'reading','Why does philanthropy raise questions for democracies?',array['Donors pay too much tax.','Donors influence public priorities without electoral accountability.','Charities are illegal.','Hospitals refuse donations.']::text[],'B','''It exercises considerable influence over public priorities without being accountable to the electorate.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Large-scale philanthropy is often greeted with uncritical gratitude, yet it raises awkward questions for democratic societies. When a foundation endows a hospital wing or funds an educational reform, it exercises considerable influence over public priorities without being accountable to the electorate. Defenders contend that private donors can take risks that governments, wary of public criticism, cannot, and that some of the most successful public-health campaigns were initially privately funded. Sceptics counter that the tax relief attached to charitable giving means that the public effectively subsidises decisions in which it has no say.',null,null,null,'exam'),
  ('ai:ai-batch-06:471d6f9ddf21','C2'::public.cefr_level,'reading','What argument do defenders of philanthropy make?',array['Governments never fund health campaigns.','Philanthropy has no influence.','Private donors can take risks governments avoid.','Donors pay all their taxes.']::text[],'C','''Private donors can take risks that governments, wary of public criticism, cannot.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Large-scale philanthropy is often greeted with uncritical gratitude, yet it raises awkward questions for democratic societies. When a foundation endows a hospital wing or funds an educational reform, it exercises considerable influence over public priorities without being accountable to the electorate. Defenders contend that private donors can take risks that governments, wary of public criticism, cannot, and that some of the most successful public-health campaigns were initially privately funded. Sceptics counter that the tax relief attached to charitable giving means that the public effectively subsidises decisions in which it has no say.',null,null,null,'exam'),
  ('ai:ai-batch-06:3fa78eaa7e14','C2'::public.cefr_level,'reading','What point do sceptics make about tax relief?',array['Tax relief makes giving illegal.','Donors don''t receive any tax relief.','The public effectively subsidises decisions it cannot influence.','Tax relief should be increased.']::text[],'C','''The public effectively subsidises decisions in which it has no say.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Large-scale philanthropy is often greeted with uncritical gratitude, yet it raises awkward questions for democratic societies. When a foundation endows a hospital wing or funds an educational reform, it exercises considerable influence over public priorities without being accountable to the electorate. Defenders contend that private donors can take risks that governments, wary of public criticism, cannot, and that some of the most successful public-health campaigns were initially privately funded. Sceptics counter that the tax relief attached to charitable giving means that the public effectively subsidises decisions in which it has no say.',null,null,null,'exam'),
  ('ai:ai-batch-06:cecb1ee8cfc1','C2'::public.cefr_level,'reading','What does the Mercator projection preserve, according to the text?',array['distances between all places','angles','areas','the size of polar regions']::text[],'B','''Preserves angles at the expense of area.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Maps carry an aura of objectivity that belies the choices underpinning them. Every projection of a spherical earth onto a flat surface involves distortion; the familiar Mercator projection, devised for navigation, preserves angles at the expense of area, making regions near the poles appear far larger than they are. Such technical compromises acquire political overtones when maps are used to represent the relative importance of nations. Beyond projection, cartographers decide what to include, what to name and in which language, decisions that have at times been instrumental in asserting territorial claims.',null,null,null,'exam'),
  ('ai:ai-batch-06:8952e7c6f24c','C2'::public.cefr_level,'reading','What effect does the Mercator projection have on regions near the poles?',array['They look much larger than they are.','They look smaller.','They disappear.','They are shown accurately.']::text[],'A','''Making regions near the poles appear far larger than they are.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Maps carry an aura of objectivity that belies the choices underpinning them. Every projection of a spherical earth onto a flat surface involves distortion; the familiar Mercator projection, devised for navigation, preserves angles at the expense of area, making regions near the poles appear far larger than they are. Such technical compromises acquire political overtones when maps are used to represent the relative importance of nations. Beyond projection, cartographers decide what to include, what to name and in which language, decisions that have at times been instrumental in asserting territorial claims.',null,null,null,'exam'),
  ('ai:ai-batch-06:3dd0bfd2a58c','C2'::public.cefr_level,'reading','How have cartographers'' decisions sometimes been used politically?',array['to teach geography','to improve navigation','to reduce distortion','to support territorial claims']::text[],'D','Decisions ''have at times been instrumental in asserting territorial claims.''',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Maps carry an aura of objectivity that belies the choices underpinning them. Every projection of a spherical earth onto a flat surface involves distortion; the familiar Mercator projection, devised for navigation, preserves angles at the expense of area, making regions near the poles appear far larger than they are. Such technical compromises acquire political overtones when maps are used to represent the relative importance of nations. Beyond projection, cartographers decide what to include, what to name and in which language, decisions that have at times been instrumental in asserting territorial claims.',null,null,null,'exam'),
  ('ai:ai-batch-06:06f8bc52765a','C2'::public.cefr_level,'reading','What does ''belies'' mean in the first sentence?',array['exaggerates','explains','hides or contradicts','confirms']::text[],'C','The aura of objectivity belies (disguises) the choices behind maps.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Maps carry an aura of objectivity that belies the choices underpinning them. Every projection of a spherical earth onto a flat surface involves distortion; the familiar Mercator projection, devised for navigation, preserves angles at the expense of area, making regions near the poles appear far larger than they are. Such technical compromises acquire political overtones when maps are used to represent the relative importance of nations. Beyond projection, cartographers decide what to include, what to name and in which language, decisions that have at times been instrumental in asserting territorial claims.',null,null,null,'exam'),
  ('ai:ai-batch-06:265060620fc7','C2'::public.cefr_level,'reading','Which choice is NOT mentioned as one cartographers make?',array['what to include','the paper the map is printed on','which language to use','what to name']::text[],'B','The text mentions inclusion, naming and language.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Maps carry an aura of objectivity that belies the choices underpinning them. Every projection of a spherical earth onto a flat surface involves distortion; the familiar Mercator projection, devised for navigation, preserves angles at the expense of area, making regions near the poles appear far larger than they are. Such technical compromises acquire political overtones when maps are used to represent the relative importance of nations. Beyond projection, cartographers decide what to include, what to name and in which language, decisions that have at times been instrumental in asserting territorial claims.',null,null,null,'exam'),
  ('ai:ai-batch-06:e4075fbcbaf8','C2'::public.cefr_level,'reading','What does the writer imply about ''reliable''?',array['It is an abbreviation.','It was invented by Swift.','Commentators once disliked it, though it is now standard.','It is still considered incorrect.']::text[],'C','Later commentators ''deplored ''reliable'' as an ugly hybrid'', yet it is now normal.',array['exam','reading']::text[],'draft','unreviewed','ai-draft:ai-batch-06','Complaints about the degeneration of English are almost as old as the language itself. Jonathan Swift lamented the introduction of abbreviations such as ''mob''; later commentators deplored ''reliable'' as an ugly hybrid. What such complaints tend to overlook is that change is not decay but the normal condition of every living language, and that today''s solecism is frequently tomorrow''s standard usage. Linguists are not, however, indifferent to how language is used; their objection is to the conflation of prestige with correctness, whereby the habits of a particular social group are presented as the logical rules of the language.',null,null,null,'exam'),
  ('ai:ai-batch-06:e580f3add42e','C2'::public.cefr_level,'grammar','Try ___ they might, the negotiators could not break the deadlock.',array['though','how','so','as']::text[],'D','''Try as they might'' = however hard they tried.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:272f408abcee','C2'::public.cefr_level,'grammar','Be that as it ___, we still need a decision by Friday.',array['is','will','might','may']::text[],'D','''Be that as it may'' = nevertheless.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d5b3cedd3564','C2'::public.cefr_level,'grammar','It is imperative that the data ___ independently verified.',array['is','are','be','will be']::text[],'C','Mandative subjunctive after ''imperative that''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a80c097888f4','C2'::public.cefr_level,'grammar','Not until the final chapter ___ the narrator''s true identity revealed.',array['it is','does','has been to','is']::text[],'D','''Not until...'' at the start causes inversion: ''is the identity revealed''.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:994a1eecda8d','C2'::public.cefr_level,'grammar','Should the need ___, additional staff will be recruited.',array['arise','arising','arose','arises']::text[],'A','''Should + subject + base form'' = if the need arises.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:c5adf5339fe3','C2'::public.cefr_level,'grammar','She has, ___ all accounts, been an exemplary colleague.',array['from','on','in','by']::text[],'D','''By all accounts'' = according to what everyone says.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:da4cbca012c3','C2'::public.cefr_level,'grammar','The findings are, if anything, ___ than expected.',array['more alarming','most alarming','alarminger','alarming']::text[],'A','''If anything'' + comparative suggests the opposite of what might be expected.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:fd5da32c9627','C2'::public.cefr_level,'grammar','Inasmuch ___ the board approved the plan, it shares responsibility.',array['to','as','so','that']::text[],'B','''Inasmuch as'' = to the extent that.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:1cda3fb93aef','C2'::public.cefr_level,'grammar','But ___ his outspoken criticism, he would have been promoted.',array['with','for','from','by']::text[],'B','''But for'' = if it were not for.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:e732c7c69166','C2'::public.cefr_level,'grammar','___ the case may be, the procedure remains the same.',array['Whichever way','Whether','Whatever','However']::text[],'C','''Whatever the case may be'' = in any case.',array['exam','grammar']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:0e8611d44420','C2'::public.cefr_level,'vocabulary','The report makes for ___ reading.',array['sobered','sobering','sobriety','somber of']::text[],'B','''Make for sobering reading'' = cause serious thought.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:4179356c31e1','C2'::public.cefr_level,'vocabulary','His rise to power was ___.',array['metaphoric','meteoric','meteorological','metabolic']::text[],'B','Meteoric = very rapid.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:ea562ca021b3','C2'::public.cefr_level,'vocabulary','The two parties have reached an ___ agreement, pending final approval.',array['on-principle','of-principle','in-principle','at-principle']::text[],'C','An agreement in principle is agreed generally but not in detail.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:1752e161e3b4','C2'::public.cefr_level,'vocabulary','The campaign gained ___ after the celebrity endorsement.',array['tractor','traction','tracking','attraction of']::text[],'B','Gain traction = become popular or accepted.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:5b440c298dd6','C2'::public.cefr_level,'vocabulary','The museum''s acquisition was ___ by controversy.',array['dogged','doggy','dodged','dug']::text[],'A','Dogged by = continually troubled by.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:b08526a3904f','C2'::public.cefr_level,'vocabulary','The author''s latest work is a ___ departure from her earlier style.',array['marking','markedly','marked','marketed']::text[],'C','A marked departure = a noticeable change.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:28c12c4e5b24','C2'::public.cefr_level,'vocabulary','The evidence against him was ___.',array['overweening','overwhelming','overworked','overwrought']::text[],'B','Overwhelming = very great in amount or strength.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:0b0a16361195','C2'::public.cefr_level,'vocabulary','The proposal was rejected on the ___ that it was too costly.',array['terms','grounds','reasons of','bases']::text[],'B','''On the grounds that'' = because.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:2b3a68a9af68','C2'::public.cefr_level,'vocabulary','She ___ through the report in under an hour.',array['ploughed','plodded off','pruned','plotted']::text[],'A','To plough through = read with effort.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a656cb92c8f2','C2'::public.cefr_level,'vocabulary','There is a ___ line between persuasion and manipulation.',array['narrow of','thin out','slim of','fine']::text[],'D','''A fine line'' = a small difference.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:9819b892424d','C2'::public.cefr_level,'vocabulary','The company''s ___ for innovation has made it an industry leader.',array['penitent','pendant','pennant','penchant']::text[],'D','A penchant = a strong liking.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:5eef46c476c3','C2'::public.cefr_level,'vocabulary','The government has been ___ for its handling of the crisis.',array['pillaged','pilfered','pilloried','pillowed']::text[],'C','Pilloried = strongly criticised in public.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:37abb1007471','C2'::public.cefr_level,'vocabulary','The terms of the agreement are ___ to change without notice.',array['subject','subjected','subjective','subjugated']::text[],'A','''Subject to'' = may be affected by.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:a51bb66e1866','C2'::public.cefr_level,'vocabulary','Her arguments were ___ and well supported.',array['incisive','inclusive','incessant','indecisive']::text[],'A','Incisive = clear and sharp.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:2b7b0ef75fe8','C2'::public.cefr_level,'vocabulary','The novel is a ___ satire of Victorian society.',array['bitter of','biting','bite','bitten']::text[],'B','A biting satire is sharp and critical.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:567bc6dec1e6','C2'::public.cefr_level,'vocabulary','The investigation uncovered a ___ of corruption.',array['net of','knot','web','mesh']::text[],'C','''A web of corruption'' = a complex network.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:88b23d6b6541','C2'::public.cefr_level,'vocabulary','They are ___ to agree on anything.',array['loathing','loathe','loath','loathsome']::text[],'C','Loath (adjective) = unwilling; loathe (verb) = hate.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:6821b8a5ee02','C2'::public.cefr_level,'vocabulary','The proposal was quietly ___.',array['jutted','jestered','jetted','jettisoned']::text[],'D','Jettisoned = abandoned.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam'),
  ('ai:ai-batch-06:d8d319bea703','C2'::public.cefr_level,'vocabulary','He gave a ___ account of the events, omitting key details.',array['selected','collective','elective','selective']::text[],'D','A selective account includes only some facts.',array['exam','vocabulary']::text[],'draft','unreviewed','ai-draft:ai-batch-06',null,null,null,null,'exam')
on conflict (external_ref) do update set
  cefr_level = excluded.cefr_level, skill = excluded.skill, prompt = excluded.prompt,
  options = excluded.options, correct_option = excluded.correct_option,
  explanation = excluded.explanation, tags = excluded.tags, passage = excluded.passage,
  media_type = excluded.media_type, media_path = excluded.media_path, media_caption = excluded.media_caption,
  pool = excluded.pool
where public.assessment_questions.status = 'draft' and public.assessment_questions.review_status = 'unreviewed';
